<?php $extra_js = <<<'JS'
async function updateServerStatuses(){document.querySelectorAll('[data-server-slug]').forEach(async card=>{try{const response=await fetch(`api/server-status.php?slug=${encodeURIComponent(card.dataset.serverSlug)}&_=${Date.now()}`,{cache:'no-store'});const data=await response.json();const online=data.status==='online';card.querySelector('[data-status-badge]').className=online?'status-badge':'status-badge status-offline';card.querySelector('[data-status-text]').textContent=online?'在线':'离线';card.querySelector('[data-players]').textContent=online&&data.players?`${data.players.online}/${data.players.max}`:'0';card.querySelector('[data-version]').textContent=online?(data.version||'--'):'--';card.querySelector('[data-gamemode]').textContent=online?(data.gamemode||'生存'):'--';card.querySelector('[data-motd]').textContent=online?(data.motd||'-'):'服务器离线'}catch(error){card.querySelector('[data-status-badge]').className='status-badge status-offline';card.querySelector('[data-status-text]').textContent='查询失败'}})}setInterval(updateServerStatuses,30000);updateServerStatuses();
JS; require __DIR__ . '/includes/footer.php'; ?>
